    fn photo_tiles(
        &self,
        layout: Tiles,
        progress: f32,
        radius: Pixels,
        p: Paint,
        cx: &mut Context<Self>,
    ) -> Div {
        let scroll_y = self.scroll.offset().y;
        let still = disabled_motion(cx);
        div()
            .relative()
            .w_full()
            .h(layout.height(self.photos.len()))
            .children(self.photos.iter().enumerate().map(|(i, photo)| {
                let b = if still {
                    self.cell(layout, i, progress)
                } else {
                    self.pinched_cell(layout, i, progress)
                };
                let favorite = self.is_favorite(&photo.id);
                let name = if favorite {
                    format!("{}, {}", photo.alt, tr(cx, "favorite", "已收藏")).into()
                } else {
                    photo.alt.clone()
                };
                div()
                    .id(("photo-cell", i))
                    .debug_selector(move || format!("photo-cell-{i}"))
                    .role(Role::Button)
                    .aria_label(name)
                    .track_focus(&self.focus[i])
                    .tab_index(
                        if i == self.focused && (self.active.is_none() || self.closing) {
                            0
                        } else {
                            -1
                        },
                    )
                    .absolute()
                    .left(b.left())
                    .top(b.top() - scroll_y)
                    .w(b.size.width)
                    .h(b.size.height)
                    .rounded(radius)
                    .overflow_hidden()
                    .bg(p.hover)
                    .cursor_pointer()
                    .child(
                        img(photo.thumbnail())
                            .size_full()
                            .rounded(radius)
                            .object_fit(ObjectFit::Cover),
                    )
                    .when(favorite, |d| {
                        d.child(
                            div()
                                .absolute()
                                .left(px(6.))
                                .bottom(px(5.))
                                .child(heart(white(), true)),
                        )
                    })
                    .focus_visible(move |d| {
                        d.shadow(vec![
                            BoxShadow::new(px(0.), px(0.), p.bright).spread_radius(px(1.)),
                        ])
                    })
                    .on_key_down(
                        cx.listener(move |s, e: &KeyDownEvent, w, cx| s.grid_key(i, e, w, cx)),
                    )
                    .on_click(cx.listener(move |s, _, w, cx| s.open(i, w, cx)))
            }))
    }

    fn thumbnail_width(&self, i: usize, height: Pixels) -> Pixels {
        (height * self.photos[i].ratio()).clamp(px(22.), px(60.))
    }

    fn filmstrip(
        &self,
        i: usize,
        width: Pixels,
        compact: bool,
        page: f32,
        p: Paint,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let thumb_h = px(if compact { 36. } else { 40. });
        let first = i.saturating_sub(12);
        let last = (i + 13).min(self.photos.len());
        let pitch = self.strip_pitch();
        let collapsed = pitch - GAP;
        let old = self.previous.map(|(old, _)| old);
        let thumb_width = |j| {
            let emphasis = if j == i {
                page
            } else if Some(j) == old {
                1. - page
            } else {
                0.
            };
            collapsed + (self.thumbnail_width(j, thumb_h) - collapsed) * emphasis
        };
        let from_center: Pixels = (first..i).map(|j| thumb_width(j) + GAP).sum();
        let travel = old.map_or(px(0.), |old| {
            (pitch * (i as f32 - old as f32)).clamp(-width, width)
        }) * (1. - page);
        let value = if tr(cx, "en", "zh") == "zh" {
            format!(
                "{}，第 {} 张，共 {} 张",
                self.photos[i].title,
                i + 1,
                self.photos.len()
            )
        } else {
            format!(
                "{}, {} of {}",
                self.photos[i].title,
                i + 1,
                self.photos.len()
            )
        };
        div()
            .id("photo-strip")
            .debug_selector(|| "photo-strip".into())
            .role(Role::Slider)
            .aria_label(tr(cx, "Photos", "照片胶片条"))
            .aria_value(value)
            .aria_numeric_value((i + 1) as f64)
            .aria_min_numeric_value(1.)
            .aria_max_numeric_value(self.photos.len() as f64)
            .aria_numeric_value_step(1.)
            .track_focus(&self.strip)
            .tab_index(0)
            .block_mouse_except_scroll()
            .absolute()
            .bottom_0()
            .left_0()
            .w_full()
            .h(px(if compact { 60. } else { 64. }))
            .overflow_hidden()
            .on_scroll(cx.listener(Self::strip_scroll))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|s, e: &MouseDownEvent, _, _| {
                    s.start_drag(e.position, DragTarget::Strip)
                }),
            )
            .child(
                row()
                    .absolute()
                    .top(px(8.))
                    .left(width / 2. - from_center - thumb_width(i) / 2. + travel)
                    .gap(GAP)
                    .children((first..last).map(|j| {
                        div()
                            .id(("photo-strip-thumb", j))
                            .w(thumb_width(j))
                            .h(thumb_h)
                            .flex_none()
                            .relative()
                            .rounded(px(4.))
                            .overflow_hidden()
                            .cursor_pointer()
                            .opacity(if i == j { 1. } else { 0.53 })
                            .hover(|d| d.opacity(1.))
                            .child(
                                img(self.photos[j].thumbnail())
                                    .size_full()
                                    .rounded(px(4.))
                                    .object_fit(ObjectFit::Cover),
                            )
                            .when(i == j, |d| {
                                d.child(
                                    div()
                                        .absolute()
                                        .inset_0()
                                        .rounded(px(4.))
                                        .border_1()
                                        .border_color(p.bright),
                                )
                            })
                            .on_click(cx.listener(move |s, _, _, cx| s.show(j, cx)))
                    })),
            )
    }

    fn viewer_layer(
        &mut self,
        layout: Tiles,
        density: f32,
        i: usize,
        w: &mut Window,
        p: Paint,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let width = self.dimensions().width;
        let compact = width < COMPACT_WIDTH;
        let radius = surface_radius(cx);
        let photo = &self.photos[i];
        let still = disabled_motion(cx);
        let t = if still {
            self.fade.get(w, cx)
        } else {
            self.viewer.get(w, cx).clamp(0., 1.)
        };
        let page = if still {
            self.page_fade.get(w, cx)
        } else {
            self.page.get(w, cx).clamp(0., 1.)
        };
        if page >= 0.999 {
            self.previous = None;
        }
        let top = px(if compact { 64. } else { 72. });
        let room = size(width, (self.height - top - px(76.)).max(px(1.)));
        let mut target = translated(fit_image(room, photo.ratio()), point(px(0.), top));
        let drag_x = if still { 0. } else { self.pull[0].get(w, cx) };
        let drag_y = if still {
            0.
        } else {
            self.pull[1].get(w, cx).max(0.)
        };
        let scale = 1. - (drag_y / 420.).min(0.24);
        target.origin += point(
            target.size.width * (1. - scale) / 2.,
            target.size.height * (1. - scale) / 2.,
        );
        target.size.width *= scale;
        target.size.height *= scale;
        target.origin += point(px(drag_x), px(drag_y * 0.75));
        let travel_direction = self.previous.map_or(0., |(_, dir)| dir);
        if !still {
            target.origin.x += width * travel_direction * (1. - page);
        }
        let origin = translated(self.cell(layout, i, density), point(px(0.), HEADER));
        let b = if still {
            target
        } else {
            mix(origin, target, t)
        };
        let side = px(if compact { 36. } else { 40. });
        let favorite = self.is_favorite(&photo.id);
        let pop = self.heart.get(w, cx).clamp(0., 1.);
        let pos = if let Some(detail) = &photo.detail {
            format!("{detail} · {} / {}", i + 1, self.photos.len())
        } else {
            format!("{} / {}", i + 1, self.photos.len())
        };
        let dim = if still {
            t
        } else {
            t * (1. - (drag_y / 300.).min(0.65))
        };
        let place = |image: ImageSource, b: Bounds<Pixels>, opacity: f32, fit| {
            img(image)
                .absolute()
                .left(b.left())
                .top(b.top())
                .w(b.size.width)
                .h(b.size.height)
                .rounded(radius)
                .opacity(opacity)
                .object_fit(fit)
        };
        div()
            .id("photo-viewer")
            .debug_selector(|| "photo-viewer".into())
            .role(Role::Dialog)
            .aria_label(tr(cx, "Photo viewer", "照片查看器"))
            .track_focus(&self.dialog)
            .absolute()
            .inset_0()
            .rounded(radius)
            .occlude()
            .bg(p.panel.opacity(dim))
            .on_key_down(cx.listener(Self::viewer_key))
            .on_scroll(cx.listener(|s, e: &ScrollEvent, w, cx| {
                if e.source != ScrollSource::Touch {
                    return;
                }
                match e.touch_phase {
                    TouchPhase::Started => s.touch = Point::default(),
                    TouchPhase::Moved => {
                        s.touch += e.delta.pixel_delta(px(16.));
                        s.track_pull(s.touch, cx);
                    }
                    TouchPhase::Ended => s.finish_pull(s.touch, w, cx),
                    TouchPhase::Cancelled => s.return_pull(cx),
                }
                w.prevent_default();
                cx.stop_propagation();
            }))
            .child(self.drag_capture(cx))
            .when_some(self.previous, |d, (old, dir)| {
                let mut last = translated(
                    fit_image(room, self.photos[old].ratio()),
                    point(px(0.), top),
                );
                if !still {
                    last.origin.x -= width * dir * page;
                }
                d.child(place(
                    self.photos[old].source.clone(),
                    last,
                    if still { 1. - page } else { 1. },
                    ObjectFit::Contain,
                ))
            })
            .child(place(
                photo.source.clone(),
                b,
                if still { t * page } else { 1. },
                if t > 0.998 {
                    ObjectFit::Contain
                } else {
                    ObjectFit::Cover
                },
            ))
            .child(
                div()
                    .id("photo-swipe-zone")
                    .absolute()
                    .left_0()
                    .right_0()
                    .top(top)
                    .h(room.height)
                    .on_mouse_down(
                        MouseButton::Left,
                        cx.listener(|s, e: &MouseDownEvent, _, _| {
                            s.start_drag(e.position, DragTarget::Viewer)
                        }),
                    ),
            )
            .child(
                row()
                    .absolute()
                    .top(px(10.))
                    .left(px(10.))
                    .right(px(10.))
                    .gap_2()
                    .justify_between()
                    .opacity(t)
                    .child(
                        action(
                            "photo-back",
                            tr(cx, "Back to all photos", "返回所有照片"),
                            side,
                            p,
                        )
                        .debug_selector(|| "photo-back".into())
                        .track_focus(&self.back)
                        .tab_index(0)
                        .block_mouse_except_scroll()
                        .child(direction(true, true, p.ink))
                        .on_click(cx.listener(|s, _, w, cx| s.close(w, cx)))
                        .on_key_down(cx.listener(
                            |s, e: &KeyDownEvent, w, cx| {
                                if !e.is_held
                                    && matches!(e.keystroke.key.as_str(), "enter" | "space")
                                {
                                    s.close(w, cx);
                                    cx.stop_propagation();
                                }
                            },
                        )),
                    )
                    .child(
                        column()
                            .flex_1()
                            .min_w_0()
                            .items_center()
                            .child(
                                div()
                                    .max_w_full()
                                    .truncate()
                                    .text_size(px(14.))
                                    .text_color(p.ink)
                                    .child(photo.title.clone()),
                            )
                            .child(
                                div()
                                    .id("photo-position")
                                    .role(Role::Status)
                                    .max_w_full()
                                    .truncate()
                                    .text_size(px(12.))
                                    .text_color(p.secondary)
                                    .child(pos),
                            ),
                    )
                    .child(
                        action("photo-favorite", tr(cx, "Favorite", "收藏"), side, p)
                            .debug_selector(|| "photo-favorite".into())
                            .aria_toggled(if favorite {
                                Toggled::True
                            } else {
                                Toggled::False
                            })
                            .tab_index(0)
                            .block_mouse_except_scroll()
                            .child(
                                div().opacity(0.7 + 0.3 * pop).child(heart(
                                    if favorite { p.danger } else { p.ink },
                                    favorite,
                                )),
                            )
                            .on_click(cx.listener(|s, _, _, cx| s.favorite(cx)))
                            .on_key_down(cx.listener(|s, e: &KeyDownEvent, _, cx| {
                                if !e.is_held
                                    && matches!(e.keystroke.key.as_str(), "enter" | "space")
                                {
                                    s.favorite(cx);
                                    cx.stop_propagation();
                                }
                            })),
                    ),
            )
            .when(!compact, |d| {
                d.children([true, false].map(|back| {
                    let enabled = if back {
                        i > 0
                    } else {
                        i + 1 < self.photos.len()
                    };
                    action(
                        if back { "photo-prev" } else { "photo-next" },
                        if back {
                            tr(cx, "Previous photo", "上一张照片")
                        } else {
                            tr(cx, "Next photo", "下一张照片")
                        },
                        side,
                        p,
                    )
                    .absolute()
                    .top(top + room.height / 2. - side / 2.)
                    .when(back, |b| b.left(px(12.)))
                    .when(!back, |b| b.right(px(12.)))
                    .opacity(if enabled { t } else { t * 0.28 })
                    .tab_index(if enabled { 0 } else { -1 })
                    .block_mouse_except_scroll()
                    .child(direction(back, false, p.ink))
                    .on_click(cx.listener(move |s, _, _, cx| s.step(if back { -1 } else { 1 }, cx)))
                    .on_key_down(cx.listener(
                        move |s, e: &KeyDownEvent, _, cx| {
                            if !e.is_held && matches!(e.keystroke.key.as_str(), "enter" | "space") {
                                s.step(if back { -1 } else { 1 }, cx);
                                cx.stop_propagation();
                            }
                        },
                    ))
                }))
            })
            .child(
                self.filmstrip(i, width, compact, if still { 1. } else { page }, p, cx)
                    .opacity(t),
            )
    }
}

impl Render for PhotoGrid {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let radius = surface_radius(cx);
        let measured = self.dimensions().width;
        let width = if measured > px(0.) {
            measured
        } else {
            w.viewport_size().width
        };
        let tiles = Tiles::new(width, self.columns);
        let t = self.density.get(w, cx).clamp(0., 1.);
        if t >= 0.999 {
            self.reflow.clear();
        }
        let open_progress = if disabled_motion(cx) {
            self.fade.get(w, cx)
        } else {
            self.viewer.get(w, cx)
        };
        if self.closing && open_progress <= 0.001 {
            self.active = None;
            self.closing = false;
        }
        let scroll = self.scroll.clone();
        let viewer = self.active.is_some();
        let panel = self.panel.clone();
        let header = self.header(width, p, cx);
        let cells = self.photo_tiles(tiles, t, radius.min(px(6.)), p, cx);
        let grid = div()
            .id("photo-scroll")
            .debug_selector(|| "photo-scroll".into())
            .role(Role::List)
            .aria_label(format!(
                "{}, {} {}",
                self.title,
                self.photos.len(),
                tr(cx, "photos", "张照片")
            ))
            .absolute()
            .left_0()
            .right_0()
            .top(HEADER)
            .bottom_0()
            .overflow_y_scroll()
            .track_scroll(&self.scroll)
            .on_scroll(cx.listener(Self::grid_wheel))
            .on_pinch(cx.listener(|s, e: &PinchEvent, w, cx| {
                s.zoom(e.delta, e.position, e.phase, cx);
                w.prevent_default();
                cx.stop_propagation();
            }))
            .child(cells);
        let viewer_layer = self
            .active
            .map(|i| self.viewer_layer(tiles, t, i, w, p, cx));
        div()
            .id("photo-grid")
            .relative()
            .w_full()
            .h(self.height)
            .rounded(radius)
            .bg(p.panel)
            .overflow_hidden()
            .child(panel.measure())
            .child(
                canvas(
                    |_, _, _| (),
                    move |b, _, w, cx| {
                        if b.size.width != width {
                            w.request_animation_frame();
                        }
                        if let Some(host) = cx.try_global::<PhotoGridScrollRegion>() {
                            let region = if viewer {
                                b
                            } else {
                                Bounds::new(
                                    b.origin + point(px(0.), HEADER),
                                    size(b.size.width, (b.size.height - HEADER).max(px(0.))),
                                )
                            };
                            (host.0)(
                                region,
                                scroll.offset().y < px(-0.5),
                                scroll.offset().y > -scroll.max_offset().y + px(0.5),
                                viewer,
                            );
                        }
                    },
                )
                .absolute()
                .inset_0(),
            )
            .child(grid)
            .child(header)
            .children(viewer_layer)
    }
}

#[cfg(test)]
mod tests {
    use super::{GridPhoto, PhotoGrid, PhotoGridEvent};
    use gpui::{
        App, Modifiers, MouseButton, PinchEvent, TestAppContext, TouchPhase, VisualTestContext,
        point, px, size,
    };
    use std::time::Duration;

    fn album(cx: &App) -> PhotoGrid {
        let photos = (0..16)
            .map(|i| {
                GridPhoto::new(
                    i.to_string(),
                    "photo.jpg".to_owned(),
                    format!("Photo {i}"),
                    format!("Title {i}"),
                    size(px(400.), px(300.)),
                )
            })
            .collect();
        PhotoGrid::new("Album", photos, cx).with_default_favorites(["2".into(), "14".into()])
    }

    fn tick(window: &mut VisualTestContext, ms: u64) {
        window.executor().advance_clock(Duration::from_millis(ms));
        window.update(|w, cx| {
            w.simulate_next_frame(cx);
            w.refresh();
        });
        window.run_until_parked();
    }

    fn click(window: &mut VisualTestContext, name: &'static str) {
        let p = window.debug_bounds(name).unwrap().center();
        window.simulate_mouse_move(p, None, Modifiers::default());
        window.simulate_mouse_down(p, MouseButton::Left, Modifiers::default());
        window.simulate_mouse_up(p, MouseButton::Left, Modifiers::default());
    }

    #[test]
    fn gallery_keyboard_and_favorite_preserve_identity_on_dismiss() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (grid, window) = app.add_window_view(|_, cx| album(cx));
        window.simulate_resize(size(px(520.), px(400.)));
        tick(window, 1);
        let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let events_copy = events.clone();
        let _sub = window.update(|w, cx| {
            grid.read(cx).focus[0].clone().focus(w, cx);
            cx.subscribe(&grid, move |_, e: &PhotoGridEvent, _| {
                events_copy.borrow_mut().push(e.clone())
            })
        });
        window.simulate_keystrokes("right enter");
        tick(window, 700);
        assert!(window.update(|w, cx| grid.read(cx).back.is_focused(w)));
        click(window, "photo-favorite");
        window.simulate_keystrokes("right tab");
        assert!(window.update(|w, cx| grid.read(cx).dialog.contains_focused(w, cx)));
        window.simulate_keystrokes("escape");
        tick(window, 700);
        assert!(window.update(|w, cx| {
            let grid = grid.read(cx);
            grid.is_favorite("1") && grid.focus[2].is_focused(w) && grid.viewed_photo().is_none()
        }));
        assert_eq!(
            *events.borrow(),
            vec![
                PhotoGridEvent::ViewerChanged(Some("1".into())),
                PhotoGridEvent::FavoriteChanged {
                    id: "1".into(),
                    favorite: true
                },
                PhotoGridEvent::ViewerChanged(Some("2".into())),
                PhotoGridEvent::ViewerChanged(None),
            ]
        );
    }

    #[test]
    fn reflow_starts_at_the_current_cells_and_keeps_the_viewed_anchor() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (grid, window) = app.add_window_view(|_, cx| album(cx));
        window.simulate_resize(size(px(522.), px(400.)));
        tick(window, 1);
        window.update(|w, cx| grid.update(cx, |s, cx| s.focus_cell(7, w, cx)));
        tick(window, 1);
        let before = window.debug_bounds("photo-cell-7").unwrap();
        window.update(|_, cx| grid.update(cx, |s, cx| s.change_columns(2, 7, cx)));
        tick(window, 0);
        let initial = window.debug_bounds("photo-cell-7").unwrap();
        assert!((initial.top() - before.top()).abs() < px(1.));
        assert_eq!(initial.size, before.size);
        tick(window, 700);
        let after = window.debug_bounds("photo-cell-7").unwrap();
        assert!(after.size.width > before.size.width + px(70.));
        assert!((after.center().y - before.center().y).abs() < px(1.));
    }

    #[test]
    fn pinch_scales_live_and_commits_from_an_independent_initial_count() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (grid, window) = app.add_window_view(|_, cx| album(cx).with_default_columns(4));
        window.simulate_resize(size(px(522.), px(400.)));
        tick(window, 1);
        let before = window.debug_bounds("photo-cell-0").unwrap();
        let position = before.center();
        let event = |phase, delta| PinchEvent {
            position,
            delta,
            phase,
            modifiers: Default::default(),
        };
        window.simulate_event(event(TouchPhase::Started, 0.));
        window.simulate_event(event(TouchPhase::Moved, 0.20));
        tick(window, 16);
        assert_eq!(window.update(|_, cx| grid.read(cx).columns()), 4);
        let live = window.debug_bounds("photo-cell-0").unwrap();
        assert!(live.size.width > before.size.width + px(10.));
        window.simulate_event(event(TouchPhase::Ended, 0.));
        tick(window, 0);
        assert_eq!(window.update(|_, cx| grid.read(cx).columns()), 3);
        assert!(
            (window.debug_bounds("photo-cell-0").unwrap().size.width - live.size.width).abs()
                < px(1.)
        );
    }

    #[test]
    fn compact_viewer_swipe_and_downward_release() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (grid, window) = app.add_window_view(|_, cx| album(cx));
        window.simulate_resize(size(px(320.), px(400.)));
        tick(window, 1);
        click(window, "photo-cell-0");
        tick(window, 700);
        let start = point(px(160.), px(180.));
        for delta in [point(px(-90.), px(0.)), point(px(0.), px(115.))] {
            let end = start + delta;
            window.simulate_mouse_move(start, None, Modifiers::default());
            window.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
            window.simulate_mouse_move(end, MouseButton::Left, Modifiers::default());
            tick(window, 16);
            window.simulate_mouse_up(end, MouseButton::Left, Modifiers::default());
            tick(window, 700);
            let actual = window.update(|_, cx| grid.read(cx).viewed_photo().map(str::to_owned));
            assert_eq!(actual, (delta.x < px(0.)).then_some("1".into()));
        }
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Window-relative placement for transient surfaces.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Default, Clone)]
pub(crate) struct TriggerBounds(Rc<Cell<Bounds<Pixels>>>);
impl TriggerBounds {
    pub fn measure(&self) -> impl IntoElement {
        let saved = self.0.clone();
        canvas(move |b, _, _| saved.set(b), |_, _, _, _| ())
            .absolute()
            .inset_0()
    }
    pub fn get(&self) -> Bounds<Pixels> {
        self.0.get()
    }
    /// Prefer below the trigger. Flip above when it leaves more room.
    pub fn place(
        &self,
        view: Size<Pixels>,
        height: Pixels,
        gap: Pixels,
    ) -> (Point<Pixels>, Anchor) {
        let b = self.get();
        if b.bottom() + gap + height > view.height - px(10.) && b.top() > view.height - b.bottom() {
            (point(b.left(), b.top() - gap), Anchor::BottomLeft)
        } else {
            (point(b.left(), b.bottom() + gap), Anchor::TopLeft)
        }
    }
}

//! Building blocks for collection navigation and contextual disclosures.
use crate::primitives::{
    control::UiLanguage,
    family::{Paint, Slide},
    flyout::TriggerBounds,
